// Local-LLM health API -- live readout of Ollama on the NAS. Read-only.
// n8n's Code node has no global fetch; HTTP goes through this.helpers.httpRequest.
// require('fs') IS allowed (same as wf30/wf-workflow-status) and reads only the
// optional bearer file. Mirrors wf-workflow-status's shape + bearer gate.
//
// OLLAMA_BASE: from INSIDE the n8n container the host LAN IP 192.168.1.26 is
// NOT routable (verified 2026-06-15). The Ollama container is reached via the
// host-gateway alias declared in n8n's extra_hosts. Verified reachable. The
// container service name 'ollama' also works when on the same docker network.

const fs = require('fs');

const OLLAMA_BASE = 'http://host.docker.internal:11434';
const BEARER_FILE = '/home/node/.n8n/n8n-webhook-bearer.txt';
const PIN_THRESHOLD_MS = 60 * 60 * 1000; // expiry > 1h out = a pin, not a 5-min keep_alive

function readSecret(p) {
  try { return fs.readFileSync(p, 'utf8').trim(); } catch (e) { return ''; }
}

const input = $input.first().json || {};
const headers = (input.headers && typeof input.headers === 'object') ? input.headers : {};

// Bearer gate (defense in depth; the NAS being LAN/Funnel-only is the real
// boundary). If no bearer file exists, the check is skipped.
const expected = readSecret(BEARER_FILE);
const auth = String(headers.authorization || headers.Authorization || '');
const presented = auth.replace(/^Bearer\s+/i, '').trim();
if (expected && presented !== expected) {
  return [{ json: { ok: false, error: 'unauthorized' } }];
}

// Inline calls (not a nested fn) so `this` keeps the n8n helper binding.
let ps, tags, version;
try {
  ps = await this.helpers.httpRequest({ method: 'GET', url: OLLAMA_BASE + '/api/ps', json: true, timeout: 6000 });
  tags = await this.helpers.httpRequest({ method: 'GET', url: OLLAMA_BASE + '/api/tags', json: true, timeout: 6000 });
  version = await this.helpers.httpRequest({ method: 'GET', url: OLLAMA_BASE + '/api/version', json: true, timeout: 6000 });
} catch (e) {
  return [{ json: { ok: false, error: 'ollama unreachable: ' + String(e && e.message || e) } }];
}

const now = Date.now();
const loadedRaw = (ps && Array.isArray(ps.models)) ? ps.models : [];
const loaded = loadedRaw.map(m => {
  const expiresAt = m.expires_at || null;
  let pinned = false;
  if (expiresAt) {
    const t = Date.parse(expiresAt);
    // A far-future / non-counting-down expiry (keep_alive = -1) reads as pinned.
    if (!Number.isFinite(t) || (t - now) > PIN_THRESHOLD_MS) pinned = true;
  }
  return { name: m.name || m.model || '(unnamed)', size_vram: Number(m.size_vram) || null, expires_at: expiresAt, pinned };
});

const installed = ((tags && Array.isArray(tags.models)) ? tags.models : [])
  .map(m => ({ name: m.name || m.model || '(unnamed)', size: Number(m.size) || null }));

return [{ json: {
  ok: true,
  generated_at: new Date().toISOString(),
  version: (version && version.version) ? String(version.version) : null,
  loaded,
  installed,
  loaded_count: loaded.length,
  installed_count: installed.length,
  any_pinned: loaded.some(m => m.pinned),
} }];
